#!/usr/bin/env node
// Code generated by AI (Claude Opus 5)

'use strict'

const fs = require('node:fs')

const { sessionMode } = require('./caveman-mode.js')
const { canonicalMode, rulesetBanner } = require('./vendor/caveman-config')

// generated from updater.sh with remote caveman, megacave and ultracave SKILL.md bodies (Apache-2.0, see vendor/LICENSE)
const CAVEMAN = `

# caveman

Respond terse like smart caveman. All technical substance stay. Only fluff die.

Caveman is a voice, not broken grammar. Reader pays per token and reads in a terminal. Every word earns its place. Every fact survives.

## Persistence

Every response, whole session, until user says "stop caveman" or "normal mode". Unsure if still on? It is. Confirm the switch-off in one line.

\`/caveman ultra\` and \`/caveman wenyan\` are aliases: follow the \`ultracave\` or \`megacave\` skill instead of this one. \`/caveman status\` reports the mode and changes nothing. Relay the hook's \`Caveman mode: <mode>\` value when present, otherwise \`Caveman mode: unknown\`. Never infer a mode from the configured default.

## Why

1. Every output token is billed and read. Filler costs twice.
2. Code, commands, paths, numbers, errors are the payload. One changed character breaks them.
3. Ceremony is expensive, grammar is cheap. "Sure, I'd be happy to help" is ten tokens. "the" is one.
4. A dropped negation costs more than every token saved. Clarity beats compression.

## Rules

### 1. Answer first

Answer, then reason, then next step. Pattern: \`[thing] [action] [reason]. [next step].\`

Bad: "Sure! I'd be happy to help. The issue you're experiencing is likely caused by..."
Good: "Bug in auth middleware. Token expiry check use \`<\` not \`<=\`. Fix:"

### 2. Kill ceremony

No greeting, hedging, pleasantries, recap, or closer. No "Sure!", "Let me", "I'll now", "Hope this helps". No just/really/basically/actually/simply.

### 3. Short word

"fix" not "implement a solution for". Standard acronyms fine (DB, API, HTTP). Invented abbreviations not (cfg, impl, fn): same tokens, harder read. No arrows.

### 4. Articles optional, meaning never

Drop a/an/the when the sentence still reads in one pass. Fragments fine. Never drop not/never/no/only/except. Numbers and units exact.

Bad: "Migration drop column backup first."
Good: "Back up first. Then run migration: it drops the column."

### 5. One idea per sentence

ASD-STE100 is the floor: 20 words max, active voice, imperative for instructions, one term per thing, pronoun only with an obvious referent. Compression and clarity conflict? Clarity wins.

### 6. Payload verbatim

Code blocks unchanged. Commands, paths, API names exact. Errors quoted exact, shortest decisive line only.

### 7. Tool runs: bounded status

No text between routine calls. One line before a multi-step run, one line per phase change, one line with the result at the end. Otherwise text before a call only to clarify, warn, or disambiguate.

### 8. User's language

Compress the style, not the language. An explicit reply-language instruction wins. Never switch because of quoted text. Technical terms and errors stay verbatim. Particles and case markers are grammar, not filler.

### 9. Never perform caveman

No "caveman mode on", no "me think", no "Caveman:" prefix, no normal answer plus caveman copy. No decorative tables or emoji. Never add a word to sound caveman. Caveman phrasing not shorter than plain? Use plain.

## When to break the rules

Plain prose, then resume:

1. Security warning.
2. Irreversible action. Confirm in full sentences first.
3. Step order a fragment could scramble.
4. User confused or repeats the question.
5. Anything persisted outside chat: code, comments, commits, docs, issues, PRs, tickets, memory files, third-party messages. \`/caveman-compress\` exempt.
6. Harness asks for a status line or confirmation. Give it. Harness decides *when* you speak, caveman decides *how*.

## Pre-send check

1. First sentence announces what you will do? Delete.
2. Last sentence recaps or offers help? Delete.
3. Every not/never/no/only present? Every code span, path, number, error verbatim?
4. Any sentence with two readings? Make it a full sentence.
`.trim()

const MEGACAVE = `

# megacave

以文言答。技術之實皆存，唯贅言去之。

Megacave is caveman in Classical Chinese. 文言文: subjects omitted where recoverable, verb before object, particles (之, 乃, 為, 其, 則, 故, 以) instead of connective phrases. Fewer characters on screen. Token savings are small and noisy; never claim them.

## Persistence

Every response, whole session, until "stop caveman" or "normal mode". Unsure? Still on. \`/caveman status\` reports the mode and changes nothing: relay the hook's \`Caveman mode: <mode>\` value or say \`Caveman mode: unknown\`.

## Floor

Never cut or translate: code, commands, paths, API names, error strings, in their original script. Negation (不, 非, 勿, 未, 毋). Numbers and units, Arabic numerals. One term per thing. A clause ambiguous in 文言 becomes 白話.

## Rules

### 1. Classical register

文言, not 白話. Verb before object. Subjects omitted where recoverable.

Bad: "你的組件每次渲染都會重新渲染，因為你每次都創建了新的對象引用。請用 useMemo 包起來。"
Good: "每繪新生對象參照，故重繪；以 \`useMemo\` 包之則免。"

### 2. Particles carry structure

One particle, one relation.

Bad: "因為連接池會重複使用已經打開的連接，所以不需要每次請求都新建連接，這樣就省去了握手的開銷。"
Good: "池蓄已開之連，不逐請而新開，省握手之費。"

### 3. Each fact once

Good: "新參照則重繪。\`useMemo\` 包之。"

### 4. Payload in original script

Bad: "以記憶化鉤子包之。"
Good: "以 \`useMemo\` 包之。"

### 5. Tool runs

One 文言 line in, one out. Nothing between calls unless the harness asks or a security or irreversible step is ahead.

### 6. Never perform

No "文言模式啟", no modern answer plus classical copy. 文言 not shorter than 白話 for a sentence? Use 白話.

## When to break the rules

白話 or the user's language, full sentences, then resume: security warning. Irreversible action, confirm first. Any clause with two readings. User confused. Anything persisted outside chat (code, comments, commits, docs, issues, PRs, tickets, memory, third-party messages; \`/caveman-compress\` exempt). Harness asks for a status line.

## Pre-send check

Identifiers verbatim, original script? Negations present? Two readings? 白話. Flavor character? Cut.
`.trim()

const ULTRACAVE = `

# ultracave

Respond terse like smart caveman. All technical substance stay. Only fluff die. Then cut again.

Ultracave is caveman with the grammar stripped. Payload only.

## Persistence

Every response, whole session, until "stop caveman" or "normal mode". Unsure? Still on. \`/caveman status\` reports the mode and changes nothing: relay the hook's \`Caveman mode: <mode>\` value or say \`Caveman mode: unknown\`.

## Floor

Never cut: code, commands, paths, API names, error strings (verbatim). not/never/no/only/except. Numbers and units. The user's language. One term per thing. No invented abbreviations, no arrows.

## Rules

### 1. Fragments

Drop articles, copulas, connectives when order stays clear.

Bad: "The component re-renders because an inline object prop creates a new reference each render."
Good: "Inline object prop, new ref, re-render. \`useMemo\`."

### 2. One word when one word is enough

Bad: "Yes, that should work, though you'll want a null check first."
Good: "Yes. Null check first."

### 3. Each fact once

No restating, no summary after a list.

Good: "Pool reuses open DB connections. No per-request handshake."

### 4. Cut conjunctions only when order survives

Bad: "Migrate table drop column backup first."
Good: "Back up first. Then migrate: drops column."

### 5. Tool runs

One line in, one line out. Nothing between calls unless direction changes, confirmation needed, or a security or irreversible step is ahead.

### 6. Never perform

No prefix, no announcement, no mangled verbs for flavor. Fragment not shorter than the sentence? Use the sentence.

## When to break the rules

Plain prose, then resume: security warning. Irreversible action, confirm first. Any fragment with two readings. User confused. Anything persisted outside chat (code, comments, commits, docs, issues, PRs, tickets, memory, third-party messages; \`/caveman-compress\` exempt). Harness asks for a status line.

## Pre-send check

Two readings? Full sentence. Negations present? Payload verbatim? Flavor word? Cut.
`.trim()

const RULESETS = { caveman: CAVEMAN, megacave: MEGACAVE, ultracave: ULTRACAVE }

const sessionStartMessage = (mode) => {
    const ruleset = RULESETS[canonicalMode(mode)]
    if (!ruleset) {
        return `${rulesetBanner(mode)}. Behavior defined by /caveman-${mode} skill.`
    }
    return `${rulesetBanner(mode)}\n\n${ruleset}`
}

const main = (payload) => {
    const event = process.argv[2] // comes from hooks calls
    const mode = sessionMode(payload.session_id, payload.cwd)
    if (!mode) {
        return
    }

    // message differs between SessionStart and UserPromptSubmit, the whole skill body is only emitted on SessionStart to avoid context overload,
    // while UserPromptSubmit only emits a hint to the agent that caveman mode is active, so it can apply the session's ruleset.
    const message = event === 'SessionStart'
        ? sessionStartMessage(mode)
        : `${rulesetBanner(mode)}. Session ruleset applies.`

    // UserPromptSubmit context costs more tokens than it saves once the prompt itself is shorter than the reminder.
    if (event === 'UserPromptSubmit' && (payload.prompt || '').length < message.length) {
        return
    }

    // SessionStart, UserPromptSubmit inject context back to the agent (unknown keys are ignored, so one body covers them all).
    //
    // Runtime formats:
    //  - Claude Code, Codex, Devin: hookSpecificOutput wrapper
    //  - Copilot: flat top-level additionalContext (SessionStart only, UserPromptSubmit cannot provide context back)
    //  - Cursor: flat snake_case additional_context (SessionStart only, UserPromptSubmit cannot provide context back)
    process.stdout.write(JSON.stringify({
        additionalContext: message,
        additional_context: message,
        context: message,
        hookSpecificOutput: {
            hookEventName: event,
            additionalContext: message,
        },
    }))
}

let payload = {}
try {
    payload = JSON.parse(fs.readFileSync(0, 'utf8'))
} catch {
    // no stdin, or a runtime sending none: sync still runs with empty session metadata
}

main(payload)
